#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Load ELF binary
const elfFile = '/app/doomgeneric_mips';
const elfData = fs.readFileSync(elfFile);

// Simple ELF parser
function parseELF(data) {
  const dv = new DataView(data.buffer, data.byteOffset, data.byteLength);

  // ELF header
  const magic = dv.getUint32(0, true);
  if (magic !== 0x464c457f) throw new Error('Invalid ELF magic');

  const elfClass = data[4]; // 1=32-bit, 2=64-bit
  const elfData = data[5];  // 1=little-endian, 2=big-endian
  const entryPoint = dv.getUint32(0x18, elfData === 1);
  const phOffset = dv.getUint32(0x1c, elfData === 1);
  const phNum = dv.getUint16(0x2c, elfData === 1);

  console.log(`ELF Entry: 0x${entryPoint.toString(16)}, PH offset: 0x${phOffset.toString(16)}, PH count: ${phNum}`);

  const segments = [];
  for (let i = 0; i < phNum; i++) {
    const offset = phOffset + i * 32;
    const type = dv.getUint32(offset, true);
    const fileOffset = dv.getUint32(offset + 4, true);
    const vAddr = dv.getUint32(offset + 8, true);
    const fileSize = dv.getUint32(offset + 16, true);
    const memSize = dv.getUint32(offset + 20, true);
    const flags = dv.getUint32(offset + 24, true);

    if (type === 1) { // PT_LOAD
      segments.push({
        vAddr, fileOffset, fileSize, memSize, flags
      });
      console.log(`Segment: vAddr=0x${vAddr.toString(16)}, fileSize=0x${fileSize.toString(16)}, memSize=0x${memSize.toString(16)}`);
    }
  }

  return { entryPoint, segments, elfData };
}

const elf = parseELF(Buffer.from(elfData));

// Memory (4GB virtual, but we'll use sparse mapping)
const memory = new Map();

function memRead32(addr) {
  const base = addr & ~0xfff;
  if (!memory.has(base)) return 0;
  const page = memory.get(base);
  const offset = addr & 0xfff;
  const dv = new DataView(page.buffer, page.byteOffset, page.byteLength);
  return dv.getUint32(offset, true);
}

function memWrite32(addr, value) {
  const base = addr & ~0xfff;
  if (!memory.has(base)) {
    memory.set(base, new Uint8Array(4096));
  }
  const page = memory.get(base);
  const offset = addr & 0xfff;
  const dv = new DataView(page.buffer, page.byteOffset, page.byteLength);
  dv.setUint32(offset, value, true);
}

function memRead8(addr) {
  const base = addr & ~0xfff;
  if (!memory.has(base)) return 0;
  const page = memory.get(base);
  return page[addr & 0xfff];
}

function memWrite8(addr, value) {
  const base = addr & ~0xfff;
  if (!memory.has(base)) {
    memory.set(base, new Uint8Array(4096));
  }
  const page = memory.get(base);
  page[addr & 0xfff] = value;
}

// Load segments into memory
for (const seg of elf.segments) {
  for (let i = 0; i < seg.fileSize; i++) {
    memWrite8(seg.vAddr + i, elfData[seg.fileOffset + i]);
  }
  for (let i = seg.fileSize; i < seg.memSize; i++) {
    memWrite8(seg.vAddr + i, 0);
  }
}

